        const header_end = @as(u32, self.base) + self.size_bytes;
        if (slot_end > header_end) return null;
        const off = zbuf.readU32(self.buf, @as(usize, self.base + 52)) catch 0;
        if (off == zbuf.NullOffset) return null;
        return BinaryFuseFilterReader.init(self.buf, off) catch null;
    }

    pub fn verify(self: Self) Error!void {
        if (@as(usize, self.base) + @as(usize, self.size_bytes) > self.buf.len) return zbuf.Error.OutOfBounds;
        const header_end = @as(u32, self.base) + self.size_bytes;
        const slot_end_36 = @as(u32, self.base) + 44;
        if (slot_end_36 <= header_end) {
            const off = try zbuf.readU32(self.buf, @as(usize, self.base + 36));
            const data_len = try zbuf.readU32(self.buf, @as(usize, self.base + 40));
            if (data_len > 0) {
                _ = try zbuf.sliceAt(self.buf, off, data_len);
            }
        }
        const slot_end_arr_44 = @as(u32, self.base) + 52;
        if (slot_end_arr_44 <= header_end) {
            const index_off = try zbuf.readU32(self.buf, @as(usize, self.base + 44));
            const elem_count = try zbuf.readU32(self.buf, @as(usize, self.base + 48));
            if (elem_count > 0) {
                const index_end = @as(usize, index_off) + @as(usize, elem_count) * 4;
                if (index_end > self.buf.len) return zbuf.Error.OutOfBounds;
            }
        }
        const count_blocks: u32 = self.blocksLen();
        var i_blocks: u32 = 0;
        while (i_blocks < count_blocks) : (i_blocks += 1) {
            const child_view = try self.blocksAt(i_blocks);
            try child_view.verify();
        }
        if (self.binaryFuse()) |child_view| {
            try child_view.verify();
        }
    }
};

pub const TableIndexBuffer = struct {
    alloc: std.mem.Allocator,
    offset: u32,
    bytes: ?[]u8,
    ownership: Ownership,
    has_tail: bool,
    pub fn initWithTail(alloc: std.mem.Allocator, bytes: []u8, ownership: Ownership) Error!@This() {
        const tail = try zbuf.readMessageTail(bytes);
        if (tail.table_id != TableIndexReader.TABLE_ID) return zbuf.Error.Invalid;
        if (tail.table_version != TableIndexReader.VERSION) return zbuf.Error.Invalid;
        return .{ .alloc = alloc, .offset = tail.offset, .bytes = bytes, .ownership = ownership, .has_tail = true };
    }
    pub fn initWithOffset(alloc: std.mem.Allocator, bytes: []u8, offset: u32, ownership: Ownership) Error!@This() {
        return .{ .alloc = alloc, .offset = offset, .bytes = bytes, .ownership = ownership, .has_tail = false };
    }
    pub fn initReader(self: @This()) Error!TableIndexReader {
        const payload = self.bytes orelse return zbuf.Error.Invalid;
        return TableIndexReader.init(payload, self.offset);
    }
    pub fn cloneInto(self: @This(), alloc: std.mem.Allocator, out: *std.ArrayList(u8)) Error!u32 {
        const reader = try self.initReader();
        var writer = try TableIndexWriter.initWithBuf(alloc, out);
        try writer.setIsNone(reader.isNone());
        try writer.setIsLz4(reader.isLz4());
        try writer.setIsZstd(reader.isZstd());
        try writer.setMaxVersion(reader.maxVersion());
        try writer.setKeyCount(reader.keyCount());
        try writer.setUncompressedSize(reader.uncompressedSize());
        try writer.setCompressedSize(reader.compressedSize());
        try writer.setStaleDataSize(reader.staleDataSize());
        try writer.compressionSet(reader.compression());
        try writer.setLastKey(reader.lastKey());
        const count_blocks: u32 = reader.blocksLen();
        if (count_blocks != 0) {
            var child_offsets_blocks = try alloc.alloc(u32, @intCast(count_blocks));
            defer alloc.free(child_offsets_blocks);
            var i_blocks: u32 = 0;
            while (i_blocks < count_blocks) : (i_blocks += 1) {
                const child = try reader.blocksAt(i_blocks);
                const child_buf = try BlockIndexBuffer.initWithOffset(alloc, @constCast(reader.buf), child.base, .borrowed);
                child_offsets_blocks[@intCast(i_blocks)] = try child_buf.cloneInto(alloc, out);
            }
            try writer.setBlocks(child_offsets_blocks);
        }
        if (reader.binaryFuse()) |child| {
            const child_buf = try BinaryFuseFilterBuffer.initWithOffset(alloc, @constCast(reader.buf), child.base, .borrowed);
            const child_off = try child_buf.cloneInto(alloc, out);
            try writer.setBinaryFuse(child_off);
        }
        const result = try writer.finish();
        return result.offset;
    }
    pub fn deinit(self: *@This()) void {
        if (self.bytes) |bytes| {
            if (self.ownership == .owned) self.alloc.free(bytes);
            self.bytes = null;
            self.ownership = .borrowed;
        }
    }
};

pub const TableIndexWriter = struct {
    const Self = @This();
    buf: ?*std.ArrayList(u8),
    owns_buf: bool,
    alloc: std.mem.Allocator,
    base: u32,

    pub const VERSION: u16 = 1;
    pub const TABLE_ID: u16 = 46594;
    pub const SIZE_BYTES: u16 = 56;

    fn bufMut(self: *Self) *std.ArrayList(u8) {
        return self.buf orelse @panic("zbuf writer missing buffer");
    }

    pub fn initWithBuf(alloc: std.mem.Allocator, buf: *std.ArrayList(u8)) Error!Self {
        const base = try zbuf.reserveHeader(buf, alloc, SIZE_BYTES);
        try zbuf.writeU16At(buf.items, @as(usize, base), VERSION);
        try zbuf.writeU16At(buf.items, @as(usize, base + 2), SIZE_BYTES);
        try zbuf.patchU32(buf.items, base + 52, zbuf.NullOffset);
        return .{ .buf = buf, .owns_buf = false, .alloc = alloc, .base = base };
    }

    pub fn init(alloc: std.mem.Allocator) Error!Self {
        const owned = try alloc.create(std.ArrayList(u8));
        owned.* = .empty;
        errdefer alloc.destroy(owned);
        const base = try zbuf.reserveHeader(owned, alloc, SIZE_BYTES);
        try zbuf.writeU16At(owned.items, @as(usize, base), VERSION);
        try zbuf.writeU16At(owned.items, @as(usize, base + 2), SIZE_BYTES);
        try zbuf.patchU32(owned.items, base + 52, zbuf.NullOffset);
        return .{ .buf = owned, .owns_buf = true, .alloc = alloc, .base = base };
    }

    pub fn setIsNone(self: *Self, v: bool) Error!void {
        const out = self.bufMut();
        const word_off = self.base + 28;
        var word = try zbuf.readU64(out.items, @as(usize, word_off));
        const bit = @as(u6, @intCast(0));
        if (v) {
            word |= (@as(u64, 1) << bit);
        } else {
            word &= ~(@as(u64, 1) << bit);
        }
        try zbuf.patchU64(out.items, word_off, word);
    }

    pub fn setIsLz4(self: *Self, v: bool) Error!void {
        const out = self.bufMut();
        const word_off = self.base + 28;
        var word = try zbuf.readU64(out.items, @as(usize, word_off));
        const bit = @as(u6, @intCast(1));
        if (v) {
            word |= (@as(u64, 1) << bit);
        } else {
            word &= ~(@as(u64, 1) << bit);
        }
        try zbuf.patchU64(out.items, word_off, word);
    }

    pub fn setIsZstd(self: *Self, v: bool) Error!void {
        const out = self.bufMut();
        const word_off = self.base + 28;
        var word = try zbuf.readU64(out.items, @as(usize, word_off));
        const bit = @as(u6, @intCast(2));
        if (v) {
            word |= (@as(u64, 1) << bit);
        } else {
            word &= ~(@as(u64, 1) << bit);
        }
        try zbuf.patchU64(out.items, word_off, word);
    }

    pub fn setMaxVersion(self: *Self, v: u64) Error!void {
        const out = self.bufMut();
        try zbuf.patchU64(out.items, self.base + 4, v);
    }

    pub fn setKeyCount(self: *Self, v: u32) Error!void {
        const out = self.bufMut();
        try zbuf.patchU32(out.items, self.base + 12, v);
    }

    pub fn setUncompressedSize(self: *Self, v: u32) Error!void {
        const out = self.bufMut();
        try zbuf.patchU32(out.items, self.base + 16, v);
    }

    pub fn setCompressedSize(self: *Self, v: u32) Error!void {
        const out = self.bufMut();
        try zbuf.patchU32(out.items, self.base + 20, v);
    }

    pub fn setStaleDataSize(self: *Self, v: u32) Error!void {
        const out = self.bufMut();
        try zbuf.patchU32(out.items, self.base + 24, v);
    }

    pub fn compressionSet(self: *Self, v: u64) Error!void {
        const out = self.bufMut();
        try zbuf.patchU64(out.items, self.base + 28, v);
    }

    pub fn compressionSetBit(self: *Self, bit_index: u32) Error!void {
        const out = self.bufMut();
        if (bit_index >= 64) return zbuf.Error.OutOfBounds;
        const bit = @as(u6, @intCast(bit_index % 64));
        const word_off = self.base + 28;
        var word = try zbuf.readU64(out.items, @as(usize, word_off));
        word |= (@as(u64, 1) << bit);
        try zbuf.patchU64(out.items, word_off, word);
    }

    pub fn compressionClearBit(self: *Self, bit_index: u32) Error!void {
        const out = self.bufMut();
        if (bit_index >= 64) return zbuf.Error.OutOfBounds;
        const bit = @as(u6, @intCast(bit_index % 64));
        const word_off = self.base + 28;
        var word = try zbuf.readU64(out.items, @as(usize, word_off));
        word &= ~(@as(u64, 1) << bit);
        try zbuf.patchU64(out.items, word_off, word);
    }

    pub fn compressionHasBit(self: *Self, bit_index: u32) Error!bool {
        const out = self.bufMut();
        if (bit_index >= 64) return zbuf.Error.OutOfBounds;
        const bit = @as(u6, @intCast(bit_index % 64));
        const word_off = self.base + 28;
        const word = try zbuf.readU64(out.items, @as(usize, word_off));
        return ((word >> bit) & 1) == 1;
    }

    pub fn setLastKey(self: *Self, data: []const u8) Error!void {
        const out = self.bufMut();
        if (data.len == 0) {
            try zbuf.patchU32(out.items, self.base + 36, 0);
            try zbuf.patchU32(out.items, self.base + 40, 0);
            return;
        }
        const abs_off = try zbuf.appendBytes(out, self.alloc, data);
        const off = abs_off;
        try zbuf.patchU32(out.items, self.base + 36, off);
        try zbuf.patchU32(out.items, self.base + 40, @as(u32, @intCast(data.len)));
    }

    pub fn setBlocks(self: *Self, values: []const u32) Error!void {
        const out = self.bufMut();
        if (values.len == 0) {
            try zbuf.patchU32(out.items, self.base + 44, 0);
            try zbuf.patchU32(out.items, self.base + 48, 0);
            return;
        }
        const abs_index_off = try zbuf.appendU32Slice(out, self.alloc, values);
        const index_off = abs_index_off;
        try zbuf.patchU32(out.items, self.base + 44, index_off);
        try zbuf.patchU32(out.items, self.base + 48, @as(u32, @intCast(values.len)));
    }

    pub fn setBinaryFuse(self: *Self, child_off: u32) Error!void {
        const out = self.bufMut();
        try zbuf.patchU32(out.items, self.base + 52, child_off);
    }

    pub fn set(self: *Self, values: anytype) Error!void {
        const Values = @TypeOf(values);
        if (@typeInfo(Values) != .@"struct") {
            @compileError("set() expects a struct literal like .{ .field = value }");
        }
        if (@hasField(Values, "is_none")) try self.setIsNone(@field(values, "is_none"));
        if (@hasField(Values, "is_lz4")) try self.setIsLz4(@field(values, "is_lz4"));
        if (@hasField(Values, "is_zstd")) try self.setIsZstd(@field(values, "is_zstd"));
        if (@hasField(Values, "max_version")) try self.setMaxVersion(@field(values, "max_version"));
        if (@hasField(Values, "key_count")) try self.setKeyCount(@field(values, "key_count"));
        if (@hasField(Values, "uncompressed_size")) try self.setUncompressedSize(@field(values, "uncompressed_size"));
        if (@hasField(Values, "compressed_size")) try self.setCompressedSize(@field(values, "compressed_size"));
        if (@hasField(Values, "stale_data_size")) try self.setStaleDataSize(@field(values, "stale_data_size"));
        if (@hasField(Values, "compression")) try self.compressionSet(@field(values, "compression"));
        if (@hasField(Values, "last_key")) try self.setLastKey(@field(values, "last_key"));
        if (@hasField(Values, "blocks")) try self.setBlocks(@field(values, "blocks"));
        if (@hasField(Values, "binary_fuse")) try self.setBinaryFuse(@field(values, "binary_fuse"));
    }

    pub fn finish(self: *Self) Error!TableIndexBuffer {
        if (self.owns_buf) {
            const owned = self.buf orelse return zbuf.Error.Invalid;
            const bytes = try owned.toOwnedSlice(self.alloc);
            self.alloc.destroy(owned);
            self.buf = null;
            return .{ .alloc = self.alloc, .offset = self.base, .bytes = bytes, .ownership = .owned, .has_tail = false };
        }
        return .{ .alloc = self.alloc, .offset = self.base, .bytes = null, .ownership = .borrowed, .has_tail = false };
    }

    pub fn finishWithTail(self: *Self) Error!TableIndexBuffer {
        const out = self.bufMut();
        try zbuf.appendMessageTail(out, self.alloc, TABLE_ID, VERSION, self.base);
        var result = try self.finish();
        result.has_tail = true;
        return result;
    }

    pub fn deinit(self: *Self) void {
        if (self.owns_buf) {
            const owned = self.buf orelse return;
            owned.deinit(self.alloc);
            self.alloc.destroy(owned);
            self.buf = null;
            self.base = 0;
            self.owns_buf = false;
        }
    }
};

pub const BinaryFuseFilterStruct = struct {
    seed: u64 = 0,
    segment_length: u32 = 0,
    segment_length_mask: u32 = 0,
    segment_count: u32 = 0,
    segment_count_length: u32 = 0,
    fingerprints: []u16 = &.{},

    fn fromReaderValue(alloc: std.mem.Allocator, r: BinaryFuseFilterReader) Error!BinaryFuseFilterStruct {
        var s = BinaryFuseFilterStruct{
            .seed = r.seed(),
            .segment_length = r.segmentLength(),
            .segment_length_mask = r.segmentLengthMask(),
            .segment_count = r.segmentCount(),
            .segment_count_length = r.segmentCountLength(),
        };
        errdefer s.deinit(alloc);
        s.fingerprints = try r.fingerprintsToSliceAlloc(alloc);
        return s;
    }

    pub fn fromReader(alloc: std.mem.Allocator, r: BinaryFuseFilterReader) Error!*BinaryFuseFilterStruct {
        const ptr = try alloc.create(BinaryFuseFilterStruct);
        errdefer alloc.destroy(ptr);
        ptr.* = try fromReaderValue(alloc, r);
        return ptr;
    }

    pub fn deinit(self: *BinaryFuseFilterStruct, alloc: std.mem.Allocator) void {
        alloc.free(self.fingerprints);
        self.fingerprints = &.{};
    }

    pub fn destroy(self: *BinaryFuseFilterStruct, alloc: std.mem.Allocator) void {
        self.deinit(alloc);
        alloc.destroy(self);
    }

    fn cloneValue(self: BinaryFuseFilterStruct, alloc: std.mem.Allocator) Error!BinaryFuseFilterStruct {
        var s = BinaryFuseFilterStruct{
            .seed = self.seed,
            .segment_length = self.segment_length,
            .segment_length_mask = self.segment_length_mask,
            .segment_count = self.segment_count,
            .segment_count_length = self.segment_count_length,
        };
        errdefer s.deinit(alloc);
        s.fingerprints = try alloc.dupe(u16, self.fingerprints);
        return s;
    }

    pub fn clone(self: BinaryFuseFilterStruct, alloc: std.mem.Allocator) Error!*BinaryFuseFilterStruct {
        const ptr = try alloc.create(BinaryFuseFilterStruct);
        errdefer alloc.destroy(ptr);
        ptr.* = try self.cloneValue(alloc);
        return ptr;
    }

    pub fn marshalTo(self: BinaryFuseFilterStruct, alloc: std.mem.Allocator, out: *std.ArrayList(u8)) Error!u32 {
        var writer = try BinaryFuseFilterWriter.initWithBuf(alloc, out);
        try writer.setSeed(self.seed);
        try writer.setSegmentLength(self.segment_length);
        try writer.setSegmentLengthMask(self.segment_length_mask);
        try writer.setSegmentCount(self.segment_count);
        try writer.setSegmentCountLength(self.segment_count_length);
        if (self.fingerprints.len > 0) try writer.setFingerprints(self.fingerprints);
        const result = try writer.finish();
        return result.offset;
    }
};

pub const BinaryFuseFilterReader = struct {
    const Self = @This();
    buf: []const u8,
    base: u32,
    size_bytes: u16,

    pub const VERSION: u16 = 1;
    pub const TABLE_ID: u16 = 46595;
    pub const SIZE_BYTES: u16 = 36;

    pub fn parseRoot(buf: []const u8) Error!Self {
        const tail = try zbuf.readMessageTail(buf);
        if (tail.table_id != TABLE_ID) return zbuf.Error.Invalid;
        const payload_buf = buf[0 .. buf.len - zbuf.message_tail_size];
        return init(payload_buf, tail.offset);
    }

    pub fn init(buf: []const u8, base: u32) Error!Self {
        if (@as(usize, base) + 4 > buf.len) return zbuf.Error.OutOfBounds;
        const size_bytes = try zbuf.readU16(buf, @as(usize, base + 2));
        if (@as(usize, base) + @as(usize, size_bytes) > buf.len) return zbuf.Error.OutOfBounds;
        return .{ .buf = buf, .base = base, .size_bytes = size_bytes };
    }

    pub fn seed(self: Self) u64 {
        const slot_end = @as(u32, self.base) + 12;
        const header_end = @as(u32, self.base) + self.size_bytes;
        if (slot_end > header_end) return 0;
        return zbuf.readU64(self.buf, @as(usize, self.base + 4)) catch 0;
    }

    pub fn segmentLength(self: Self) u32 {
        const slot_end = @as(u32, self.base) + 16;
        const header_end = @as(u32, self.base) + self.size_bytes;
        if (slot_end > header_end) return 0;
        return zbuf.readU32(self.buf, @as(usize, self.base + 12)) catch 0;
    }

    pub fn segmentLengthMask(self: Self) u32 {
        const slot_end = @as(u32, self.base) + 20;
        const header_end = @as(u32, self.base) + self.size_bytes;
        if (slot_end > header_end) return 0;
        return zbuf.readU32(self.buf, @as(usize, self.base + 16)) catch 0;
    }

    pub fn segmentCount(self: Self) u32 {
        const slot_end = @as(u32, self.base) + 24;
        const header_end = @as(u32, self.base) + self.size_bytes;
        if (slot_end > header_end) return 0;
        return zbuf.readU32(self.buf, @as(usize, self.base + 20)) catch 0;
    }

    pub fn segmentCountLength(self: Self) u32 {
        const slot_end = @as(u32, self.base) + 28;
        const header_end = @as(u32, self.base) + self.size_bytes;
        if (slot_end > header_end) return 0;
        return zbuf.readU32(self.buf, @as(usize, self.base + 24)) catch 0;
    }

    fn fingerprintsSlice(self: Self) []const u8 {
        const slot_end = @as(u32, self.base) + 36;
        const header_end = @as(u32, self.base) + self.size_bytes;
        if (slot_end > header_end) return &.{};
        const index_off = zbuf.readU32(self.buf, @as(usize, self.base + 28)) catch return &.{};
        const elem_count = zbuf.readU32(self.buf, @as(usize, self.base + 32)) catch return &.{};
        if (elem_count == 0) return &.{};
        const end = @as(usize, index_off) + @as(usize, elem_count) * 2;
        if (end > self.buf.len) return &.{};
        return self.buf[index_off..end];
    }

    pub fn fingerprintsLen(self: Self) u32 {
        return @intCast(self.fingerprintsSlice().len / 2);
    }

    pub fn fingerprintsAt(self: Self, i: u32) Error!u16 {
        const s = self.fingerprintsSlice();
        const off = @as(usize, i) * 2;
        if (off + 2 > s.len) return zbuf.Error.OutOfBounds;
        return zbuf.readU16(s, off) catch unreachable;
    }

    pub fn fingerprintsToSliceAlloc(self: Self, alloc: std.mem.Allocator) Error![]u16 {
        const raw = self.fingerprintsSlice();
        const count = raw.len / 2;
        const out = try alloc.alloc(u16, count);
        errdefer alloc.free(out);
        for (out, 0..) |*v, i| {
            v.* = zbuf.readU16(raw, i * 2) catch unreachable;
        }
        return out;
    }

    pub fn verify(self: Self) Error!void {
        if (@as(usize, self.base) + @as(usize, self.size_bytes) > self.buf.len) return zbuf.Error.OutOfBounds;
        const header_end = @as(u32, self.base) + self.size_bytes;
        const slot_end_arr_28 = @as(u32, self.base) + 36;
        if (slot_end_arr_28 <= header_end) {
            const index_off = try zbuf.readU32(self.buf, @as(usize, self.base + 28));
            const elem_count = try zbuf.readU32(self.buf, @as(usize, self.base + 32));
            if (elem_count > 0) {
                const index_end = @as(usize, index_off) + @as(usize, elem_count) * 2;
                if (index_end > self.buf.len) return zbuf.Error.OutOfBounds;
            }
        }
    }
};

